import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Congruenza fra triangoli","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fd/fda.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fd/fda.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fd/fda.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="congruenza-fra-triangoli" tabindex="-1">Congruenza fra triangoli <a class="header-anchor" href="#congruenza-fra-triangoli" aria-label="Permalink to “Congruenza fra triangoli”">​</a></h1><p>Per definire la congruenza fra due triangoli ci rifacciamo alla definizione di congruenza trovata nei postulati.</p><blockquote><p class="text-purple">[<strong>Definizione:</strong> Due triangoli sono congruenti se è possibile sovrapporli con un movimento rigido in modo che coincidano punto per punto]</p></blockquote><hr><p>Per capire la logica di quello che segue dobbiamo rifarci al popolo che organizzò la geometria: come studiavano geometria i Greci? La carta non esisteva e la pergamena ed il papiro erano troppo cari per sprecarli, quindi i greci si accontentavano di tracciare le figure sulla cenere del focolare, oppure, se erano ricchi avevano una stanza col pavimento di sabbia su cui tracciare le figure con un ramoscello. Oggi noi con il criterio di congruenza potremmo spostare un triangolo fatto su un foglio di carta su un altro triangolo fatto su un foglio diverso, ma i greci non potevano certo spostare la cenere oppure la sabbia. Da qui nasce l&#39;esigenza di trovare un modo per vedere se due triangoli sono uguali: basterà considerare la lunghezza dei lati spezzando un ramoscello alla giusta distanza, oppure l&#39;ampiezza degli angoli tagliando la punta di una foglia con opportuna ampiezza e confrontando così le due figure.</p><p>Ma c&#39;è bisogno di fare questo per tutti i lati e per tutti gli angoli oppure basta farlo solo per qualche lato e qualche angolo? La risposta giusta è la seconda e le scorciatoie che ne derivano saranno chiamate criteri di congruenza dei triangoli.</p><hr><p>Un criterio di congruenza dei triangoli è una <a href="./fda0.html">scorciatoia</a> che ci permette di dire quando due triangoli sono uguali senza doverli sovrapporre.</p><ul><li><a href="./fdaa.html">Primo criterio di congruenza dei triangoli</a></li><li><a href="./fdab.html">Secondo criterio di congruenza dei triangoli</a></li><li><a href="./fdac.html">Conseguenze del secondo criterio: il triangolo isoscele</a></li><li><a href="./fdad.html">Terzo criterio di congruenza dei triangoli</a></li><li><a href="./fdae.html">Applicazione dei criteri alle dimostrazioni: alcuni problemi</a></li></ul>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};